use knapsack::knapsack;

#[test]
fn test_basic() {
    // capacity=50, items: (w=10,v=60),(w=20,v=100),(w=30,v=120)
    // optimal: take items 1+2 (w=50, v=220)
    assert_eq!(knapsack(50, &[10, 20, 30], &[60, 100, 120]), 220);
}

#[test]
fn test_zero_capacity() {
    assert_eq!(knapsack(0, &[1, 2], &[10, 20]), 0);
}

#[test]
fn test_empty_items() {
    assert_eq!(knapsack(10, &[], &[]), 0);
}

#[test]
fn test_single_item_fits() {
    assert_eq!(knapsack(5, &[5], &[42]), 42);
}

#[test]
fn test_single_item_too_heavy() {
    assert_eq!(knapsack(4, &[5], &[42]), 0);
}

