Implement 0/1 knapsack in src/lib.rs.

pub fn knapsack(capacity: usize, weights: &[usize], values: &[usize]) -> usize
  // Returns the maximum value achievable using items 0..n-1 with total weight <= capacity.
  // Each item can be taken at most once.
  //
  // DP approach:
  //   dp[i][w] = max value using first i items with capacity w
  //   dp[0][w] = 0 for all w
  //   for i in 1..=n:
  //     for w in 0..=capacity:
  //       dp[i][w] = dp[i-1][w]                              (skip item i)
  //       if weights[i-1] <= w:
  //         dp[i][w] = max(dp[i][w], dp[i-1][w - weights[i-1]] + values[i-1])  (take item i)
  //   return dp[n][capacity]

All 5 tests in tests/knapsack_test.rs must pass.
